package org.apache.commons.lang3;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Random;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class RandomStringUtils_random_TriageGen0Test {

    @Test
    public void testRandom_CountZero() {
        String result = RandomStringUtils.random(0, 0, 0, true, true, null, new Random());
        assertEquals("", result);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testRandom_CountNegative() {
        RandomStringUtils.random(-1, 0, 0, true, true, null, new Random());
    }

    @Test(expected = IllegalArgumentException.class)
    public void testRandom_EmptyCharsArray() {
        RandomStringUtils.random(5, 0, 0, true, true, new char[]{}, new Random());
    }

    @Test
    public void testRandom_WithCharsArrayAndStartEndZero() {
        char[] chars = {'a', 'b', 'c'};
        // start=0, end=0, chars not null -> end becomes chars.length (3)
        String result = RandomStringUtils.random(3, 0, 0, false, false, chars, new Random());
        assertEquals(3, result.length());
        for (char c : result.toCharArray()) {
            assertTrue(c == 'a' || c == 'b' || c == 'c');
        }
    }

    @Test
    public void testRandom_NoLettersNoNumbersAndStartEndZero() {
        // start=0, end=0, chars null, !letters && !numbers -> end = Integer.MAX_VALUE, start = 0
        // We use a small count to avoid infinite loop or huge memory if random hits non-printable
        // But the logic sets end = MAX_VALUE. To test this branch safely:
        String result = RandomStringUtils.random(1, 0, 0, false, false, null, new Random());
        assertNotNull(result);
    }

    @Test
    public void testRandom_LettersOrNumbersAndStartEndZero() {
        // start=0, end=0, chars null, (letters || numbers) -> end = 'z'+1, start = ' '
        String result = RandomStringUtils.random(5, 0, 0, true, false, null, new Random());
        assertEquals(5, result.length());
    }

    @Test
    public void testRandom_WithCustomCharsRange() {
        char[] chars = {'A', 'B', 'C', 'D'};
        // start=1, end=3 (gap=2), chars not null. indices: 1, 2. chars[1]='B', chars[2]='C'
        String result = RandomStringUtils.random(5, 1, 3, false, false, chars, new Random());
        assertEquals(5, result.length());
        for (char c : result.toCharArray()) {
            assertTrue(c == 'B' || c == 'C');
        }
    }

    @Test
    public void testRandom_SurrogateLogic_LowSurrogate() {
        // 56320 to 57343 are low surrogates
        char[] chars = {56320}; 
        // We need to trigger the logic where it detects low surrogate and attempts to insert high surrogate
        // Since the method loops until count is satisfied, we can force it.
        // Note: the method uses random.nextInt(gap) + start. Gap = 1-0 = 1. index = 0.
        String result = RandomStringUtils.random(1, 0, 1, false, false, chars, new Random());
        // Because it's a low surrogate, it tries to insert a high surrogate before it.
        // However, if count was 1, it enters: if(count == 0) { count++ } 
        // Let's try count = 2 to hit the "else" branch (inserting high surrogate)
        String result2 = RandomStringUtils.random(2, 0, 1, false, false, chars, new Random());
        // The logic: buffer[count] = ch (low), count--, buffer[count] = high.
        // This results in a 2-char string.
        assertEquals(2, result2.length());
    }

    @Test
    public void testRandom_SurrogateLogic_HighSurrogate() {
        // 55296 to 56191 are high surrogates
        char[] chars = {55296};
        String result = RandomStringUtils.random(2, 0, 1, false, false, chars, new Random());
        assertEquals(2, result.length());
    }

    @Test
    public void testRandom_SurrogateLogic_PrivateSurrogate() {
        // 56192 to 56319 are private high surrogates (skipped)
        char[] chars = {56192};
        // We request 1 char. It will skip and increment count until it finds something else or loops.
        // To avoid infinite loop in test, we provide a valid char as the second option.
        char[] mixed = {56192, 'a'};
        String result = RandomStringUtils.random(1, 0, 2, false, false, mixed, new Random());
        assertEquals(1, result.length());
        assertEquals('a', result.charAt(0));
    }

    @Test
    public void testRandom_FilterLogic() {
        // Test that it only returns letters if letters=true
        char[] mixed = {'a', '1', '!'};
        // letters=true, numbers=false. 'a' is letter, '1' is digit, '!' is neither.
        // The loop will skip '1' and '!' and only pick 'a'.
        String result = RandomStringUtils.random(5, 0, 3, true, false, mixed, new Random());
        assertEquals(5, result.length());
        for (char c : result.toCharArray()) {
            assertTrue(Character.isLetter(c));
        }
    }

    @Test
    public void testRandom_FilterLogic_Numbers() {
        char[] mixed = {'a', '1', '!'};
        // letters=false, numbers=true.
        String result = RandomStringUtils.random(5, 0, 3, false, true, mixed, new Random());
        assertEquals(5, result.length());
        for (char c : result.toCharArray()) {
            assertTrue(Character.isDigit(c));
        }
    }

    @Test
    public void testRandom_FilterLogic_Neither() {
        char[] mixed = {'a', '1', '!'};
        // letters=false, numbers=false. Logic: if (!letters && !numbers)
        // This branch allows the character if it matches the !letters && !numbers condition.
        // In the code: if (letters && isLetter || numbers && isDigit || !letters && !numbers)
        // If letters=false, numbers=false, the third part of the OR is always true.
        // This effectively means it accepts any character from the array.
        String result = RandomStringUtils.random(5, 0, 3, false, false, mixed, new Random());
        assertEquals(5, result.length());
    }
}
